questions.stem:
Study the following nested loop:

for (int i = 1; i <= 3; i++) {
    for (int j = 1; j <= i; j++) {
        cout << j;
    }
    cout << endl;
}

questions.answer:
#include <iostream>
#include <string>
using namespace std;
struct Book {
    string title;
    double price;
    int quantity;
};
int main() {
    Book books[5];
    double totalValue = 0;
    int mostExpensive = 0;
    for (int i = 0; i < 5; i++) {
        cin.ignore();
        cout << "Title: ";
        getline(cin, books[i].title);
        cout << "Price and quantity: ";
        cin >> books[i].price >> books[i].quantity;
        totalValue += books[i].price * books[i].quantity;
        if (books[i].price > books[mostExpensive].price) {
            mostExpensive = i;
        }
    }
    cout << "Total inventory value: RM" << totalValue << endl;
    cout << "Most expensive: " << books[mostExpensive].title
         << " (RM" << books[mostExpensive].price << ")" << endl;
    return 0;
}

